import unreal, json, collections
les = unreal.get_editor_subsystem(unreal.LevelEditorSubsystem)
ues = unreal.get_editor_subsystem(unreal.UnrealEditorSubsystem)
original = ues.get_editor_world().get_path_name().split('.')[0]
dirty = [p.get_name() for p in unreal.EditorLoadingAndSavingUtils.get_dirty_map_packages()]
if dirty:
    print(json.dumps({'inspection_deferred': True, 'dirty_maps': dirty}))
else:
    target = '/Game/Levels/Game_Levels/Lvl_Forsaken_Castle'
    if not les.load_level(target): raise RuntimeError('Castle map failed to load')
    actors = unreal.get_editor_subsystem(unreal.EditorActorSubsystem).get_all_level_actors()
    report = {'world': ues.get_editor_world().get_path_name(), 'actor_count': len(actors), 'class_counts': dict(collections.Counter(a.get_class().get_name() for a in actors)), 'landscapes': [], 'terrain_mesh_actors': []}
    for a in actors:
        if isinstance(a, unreal.LandscapeProxy):
            row = {'name': a.get_name(), 'label': a.get_actor_label(), 'transform': str(a.get_actor_transform()), 'components': [], 'material': str(a.get_editor_property('landscape_material'))}
            for c in a.get_components_by_class(unreal.LandscapeComponent): row['components'].append({'name': c.get_name(), 'x': c.get_editor_property('section_base_x'), 'y': c.get_editor_property('section_base_y')})
            report['landscapes'].append(row)
        elif any(s in a.get_actor_label().lower() for s in ['landscape', 'terrain', 'splatmap']):
            report['terrain_mesh_actors'].append({'label': a.get_actor_label(), 'class': a.get_class().get_name(), 'meshes': [c.static_mesh.get_path_name() if c.static_mesh else None for c in a.get_components_by_class(unreal.StaticMeshComponent)]})
    print(json.dumps(report, indent=2))
    if unreal.EditorLoadingAndSavingUtils.get_dirty_map_packages():
        print('Castle remains open: map became dirty during load; no save or discard performed.')
    else:
        print('Returned to original map:', les.load_level(original))
